use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub bid_key: String,
    pub solar_arrays: i64,
    pub wind_turbines: i64,
    pub storage_banks: i64,
    pub interconnects: i64,
    pub emergency_mode: bool,
    pub duplicate_bid: bool,
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub bid_key: String,
    pub generation_units: i64,
    pub battery_buffer_units: i64,
    pub grid_required_units: i64,
    pub grid_capacity_units: i64,
    pub delivered_units: i64,
    pub shortfall_units: i64,
    pub dispatch_windows: i64,
    pub bid_score: i64,
    pub bid_state: String,
}

pub fn score(solar_arrays: i64, wind_turbines: i64, storage_banks: i64, interconnects: i64, emergency_mode: bool) -> i64 {
    let generation = solar_arrays * 9 + wind_turbines * 13;
    let buffer = storage_banks * if emergency_mode { 7 } else { 3 };
    let required = generation + buffer;
    let capacity = interconnects * 55;
    let delivered = required.min(capacity);
    let shortfall = (required - capacity).max(0);
    delivered + shortfall * 4 + (required / 31) * 9
}

pub fn calculate(v: &RequestInput) -> ResponseOutput {
    let generation_units = v.solar_arrays * 9 + v.wind_turbines * 13;
    let battery_buffer_units = v.storage_banks * if v.emergency_mode { 7 } else { 3 };
    let grid_required_units = generation_units + battery_buffer_units;
    let grid_capacity_units = v.interconnects * 55;
    let delivered_units = grid_required_units.min(grid_capacity_units);
    let shortfall_units = (grid_required_units - grid_capacity_units).max(0);
    let dispatch_windows = grid_required_units / 31;
    let bid_state = if shortfall_units == 0 { "accepted" } else if v.emergency_mode { "emergency_shortfall" } else { "routine_shortfall" };
    ResponseOutput {
        bid_key: v.bid_key.clone(), generation_units, battery_buffer_units, grid_required_units,
        grid_capacity_units, delivered_units, shortfall_units, dispatch_windows,
        bid_score: delivered_units + shortfall_units * 4 + dispatch_windows * 9,
        bid_state: bid_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_browser_score(a0: i64, a1: i64, a2: i64, a3: i64, a4: i32) -> i64 {
    score(a0, a1, a2, a3, a4 != 0)
}

